func TestCaptureDocExampleFromTestCase_UsesDocExampleConfigOverride(t *testing.T) {
	tmpDir := t.TempDir()
	tc := resource.TestCase{
		Steps: []resource.TestStep{
			{Config: `resource "f5xc_route" "test" { name = "runtime-value" namespace = "runtime" }`},
		},
	}

	override := `resource "f5xc_route" "test" { name = "example-route" namespace = "system" }`
	err := captureDocExampleFromTestCase(t, tc, VcrTestOptions{
		DocExampleCapture:    true,
		DocExampleOutputRoot: tmpDir,
		DocExampleConfig:     override,
	})
	if err != nil {
		t.Fatalf("captureDocExampleFromTestCase() error: %v", err)
	}

	outPath := filepath.Join(tmpDir, "resources", "f5xc_route", "resource_uses_doc_example_config_override.tf")
	b, readErr := os.ReadFile(outPath)
	if readErr != nil {
		t.Fatalf("expected output file at %s: %v", outPath, readErr)
	}
	got := string(b)
	if !strings.Contains(got, `name = "example-route"`) {
		t.Fatalf("expected override content in output, got: %s", got)
	}
	if strings.Contains(got, `name = "runtime-value"`) {
		t.Fatalf("output should not include runtime step config when override provided, got: %s", got)
	}
}

