// ---------------------------------------------------------------------------
// VCR record + replay round-trip integration test
// ---------------------------------------------------------------------------

func TestVCR_RecordAndReplay_RoundTrip(t *testing.T) {
	// Set up a local HTTP server to serve a test response.
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"status":"recorded"}`))
	}))
	defer srv.Close()

	cassetteName := filepath.Join(t.TempDir(), "roundtrip")

	// ---- PHASE 1: Record ----
	rec, err := recorder.New(cassetteName,
		recorder.WithMode(recorder.ModeRecordOnly),
		recorder.WithSkipRequestLatency(true),
		recorder.WithReplayableInteractions(true),
		recorder.WithHook(redactSensitiveHeaders, recorder.BeforeSaveHook),
		recorder.WithMatcher(methodURLMatcher),
	)
	if err != nil {
		t.Fatalf("failed to create recording recorder: %v", err)
	}

	// Install the VCR wrapper so transports go through the recorder.
	client.SetVCRTransportWrapper(func(_ http.RoundTripper) http.RoundTripper {
		return rec
	})

	// Make a request through the recorder.
	req, _ := http.NewRequest(http.MethodGet, srv.URL+"/api/test", nil)
	req.Header.Set("Authorization", "APIToken secret-token-123")
	resp, err := rec.RoundTrip(req)
	if err != nil {
		t.Fatalf("recording request failed: %v", err)
	}
	body, _ := io.ReadAll(resp.Body)
	resp.Body.Close()
	if string(body) != `{"status":"recorded"}` {
		t.Errorf("recorded body = %q", string(body))
	}

	// Stop the recorder to flush the cassette to disk.
	if err := rec.Stop(); err != nil {
		t.Fatalf("recorder.Stop() failed: %v", err)
	}

	// Verify cassette file exists on disk.
	cassetteFile := cassetteName + ".yaml"
	if _, err := os.Stat(cassetteFile); os.IsNotExist(err) {
		t.Fatalf("cassette file not created: %s", cassetteFile)
	}

	// ---- PHASE 2: Replay ----
	replayRec, err := recorder.New(cassetteName,
		recorder.WithMode(recorder.ModeReplayOnly),
		recorder.WithSkipRequestLatency(true),
		recorder.WithReplayableInteractions(true),
		recorder.WithMatcher(methodURLMatcher),
	)
	if err != nil {
		t.Fatalf("failed to create replay recorder: %v", err)
	}

	client.SetVCRTransportWrapper(func(_ http.RoundTripper) http.RoundTripper {
		return replayRec
	})

	// Replay the same request (without the real server).
	reqReplay, _ := http.NewRequest(http.MethodGet, srv.URL+"/api/test", nil)
	reqReplay.Header.Set("Authorization", "APIToken replay-token")
	respReplay, err := replayRec.RoundTrip(reqReplay)
	if err != nil {
		t.Fatalf("replay request failed: %v", err)
	}
	bodyReplay, _ := io.ReadAll(respReplay.Body)
	respReplay.Body.Close()
	if string(bodyReplay) != `{"status":"recorded"}` {
		t.Errorf("replayed body = %q, want recorded value", string(bodyReplay))
	}

	if err := replayRec.Stop(); err != nil {
		t.Fatalf("replay recorder.Stop() failed: %v", err)
	}

	// Restore global wrapper.
	client.SetVCRTransportWrapper(nil)
}

// TestVCR_RedactsHeadersInCassette verifies that sensitive headers are
// redacted in the cassette file on disk after recording.
func TestVCR_RedactsHeadersInCassette(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`OK`))
	}))
	defer srv.Close()

	cassetteName := filepath.Join(t.TempDir(), "redact_test")

	rec, err := recorder.New(cassetteName,
		recorder.WithMode(recorder.ModeRecordOnly),
		recorder.WithSkipRequestLatency(true),
		recorder.WithHook(redactSensitiveHeaders, recorder.BeforeSaveHook),
		recorder.WithMatcher(methodURLMatcher),
	)
	if err != nil {
		t.Fatalf("failed to create recorder: %v", err)
	}

	req, _ := http.NewRequest(http.MethodGet, srv.URL+"/secret", nil)
	req.Header.Set("Authorization", "APIToken super-secret-value")
	req.Header.Set("X-Volterra-Apigw-Tenant", "tenant-xyz")
	req.Header.Set("Cookie", "session=private")

	resp, err := rec.RoundTrip(req)
	if err != nil {
		t.Fatalf("request failed: %v", err)
	}
	resp.Body.Close()

	if err := rec.Stop(); err != nil {
		t.Fatalf("recorder.Stop() failed: %v", err)
	}

	// Read the cassette file and verify secrets are redacted.
	cassetteFile := cassetteName + ".yaml"
	data, err := os.ReadFile(cassetteFile)
	if err != nil {
		t.Fatalf("failed to read cassette: %v", err)
	}
	content := string(data)

	if strings.Contains(content, "super-secret-value") {
		t.Error("cassette contains unredacted Authorization value")
	}
	if strings.Contains(content, "tenant-xyz") {
		t.Error("cassette contains unredacted tenant header value")
	}
	if strings.Contains(content, "session=private") {
		t.Error("cassette contains unredacted cookie value")
	}
	if !strings.Contains(content, "REDACTED") {
		t.Error("cassette does not contain REDACTED placeholder")
	}
}
